if(!monthWeeks(S.month).includes(S.week))S.week=monthWeeks(S.month)[0]||monday(today());if(!themes[S.theme])S.theme='neon';if(!['dashboard','input','stores','history','settings'].includes(S.page))S.page='dashboard';

